// ===============================================================================
// DAEMIND SRE - PARSING & NORMALIZAÇÃO DE PEDIDO PIX
// ===============================================================================
const body = $json.body || $json;

// 1. Telefone normalizado com DDI 55
let rawPhone = (body.cliente_whatsapp || body.telefone || body.phone || body.customer?.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (body.cliente_nome || body.nome || body.customer?.first_name || 'Cliente').trim();
const email = (body.cliente_email || body.email || body.customer?.email || '').trim().toLowerCase();
const numeroPedido = parseInt(body.numero_pedido || body.order_number || body.id || Date.now(), 10);
const pedidoId = parseInt(body.pedido_id || body.id || numeroPedido, 10);
const valorTotal = parseFloat(body.valor_total || body.total || 0);
const pixCopiaCola = body.pix_copia_cola || body.pix_code || body.qr_code_text || '00020126580014br.gov.bcb.pix...';
const pixQrCodeUrl = body.pix_qr_code_url || body.qr_code_url || '';

return [{
  json: {
    pedido_id: pedidoId,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    whatsapp: rawPhone,
    email: email,
    valor_total: valorTotal,
    pix_copia_cola: pixCopiaCola,
    pix_qr_code_url: pixQrCodeUrl
  }
}];
